import zlib
def inflate(data,limit):
 if type(limit)is not int or limit<0:raise ValueError()
 chunks=[];remaining=data
 while remaining:
  decoder=zlib.decompressobj(31);pending=remaining
  while True:
   decoder=decoder.copy()
   part=decoder.decompress(pending,4096);chunks.append(part)
   if decoder.eof:
    remaining=decoder.unused_data;break
   pending=decoder.unconsumed_tail
   if not pending and not part:raise zlib.error('incomplete gzip stream')
 result=b''.join(chunks)
 if len(result)>limit:raise ValueError('expanded limit')
 return result

